import json, sys
BASE = "https://freya-final-mock.sarperkahvecioglu1.workers.dev/voice/v1"
OUT = sys.argv[1]

def leaf(v, desc=""):
    d = {"type": "string", "default": v}
    if desc: d["description"] = desc
    return d

def api_fn(name, path, body, hook, retries=1, timeout=25000):
    return {
        "type": "function",
        "config": {"timeoutMs": timeout, "maxRetries": retries},
        "function": {
            "name": name, "handler": "__function__:api_call",
            "description": "Engine-run call to " + path,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + path},
                "method": {"type": "string", "default": "POST"},
                "connect_retries": {"type": "number", "default": 2},
                "headers": {"type": "object", "properties": {
                    "Content-Type": {"type": "string", "default": "application/json"},
                    "Accept": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "properties": {k: leaf(v) for k, v in body.items()}, "required": list(body.keys())}
            }}
        },
        "post_process_code": hook,
    }

HOOK_HEAD = """try:
    import json
    result.pop('header', None)
    body = result.get('data')
    if not isinstance(body, dict):
        body = {}
        result['data'] = body
    sc = result.get('status_code')
    try:
        sc = int(sc)
    except Exception:
        sc = 0
    res = body.get('result') if isinstance(body.get('result'), dict) else {}
    code = str(res.get('code') or res.get('returnCode') or '')
    inner = body.get('data') if isinstance(body.get('data'), dict) else {}
    ok = (sc == 200 or sc == 0) and str(res.get('returnCode') or '') == '1' and len(inner) > 0
"""
HOOK_TAIL = """except Exception:
    try:
        result['data'] = {'%s': 'error', 'what_to_do_next': 'The service failed. Say only the fixed error sentence; claim nothing was done.'}
    except Exception:
        pass
"""

def hook(body_code, flag):
    return HOOK_HEAD + body_code + HOOK_TAIL % flag

HOOK_CARDS = hook("""    cards = inner.get('cards') if isinstance(inner.get('cards'), list) else []
    if ok and len(cards) > 0:
        body['list_status'] = 'ok'
        body['cards_json'] = json.dumps(cards, ensure_ascii=False)
        body['what_to_do_next'] = 'Cards loaded. Say nothing about this result.'
    elif sc == 404 or code == 'FB_IVR_CHANNEL_102' or (ok and len(cards) == 0):
        body['list_status'] = 'none'
        body['cards_json'] = '[]'
        body['what_to_do_next'] = 'The customer has no eligible card.'
    else:
        body['list_status'] = 'error'
        body['cards_json'] = '[]'
        body['what_to_do_next'] = 'The card service failed.'
""", "list_status")

HOOK_BAL = hook("""    if ok:
        body['bal_status'] = 'ok'
        body['balance_json'] = json.dumps(inner, ensure_ascii=False)
        body['what_to_do_next'] = 'Balance loaded. Say nothing about this result; the reading is prepared separately.'
    else:
        body['bal_status'] = 'error'
        body['balance_json'] = '{}'
        body['what_to_do_next'] = 'The balance service failed.'
""", "bal_status")

HOOK_EMAIL = hook("""    if ok:
        em = str(inner.get('ibanEmail') or '').strip()
        ctype = str(inner.get('communicationType') or '')
        if em and '@' in em and ctype != 'Phone':
            body['email_status'] = 'has_email'
            body['email_address'] = em
        else:
            body['email_status'] = 'no_email'
            body['email_address'] = ''
        body['what_to_do_next'] = 'Contact info loaded. Say nothing about this result.'
    else:
        body['email_status'] = 'error'
        body['email_address'] = ''
        body['what_to_do_next'] = 'The contact service failed.'
""", "email_status")

HOOK_SEND = hook("""    if ok and str(inner.get('exitState') or '').upper() == 'DONE':
        body['send_status'] = 'ok'
        body['what_to_do_next'] = 'The statement was sent.'
    else:
        body['send_status'] = 'error'
        body['what_to_do_next'] = 'Sending failed. Do not say it was sent.'
""", "send_status")

HOOK_WGET = hook("""    if ok:
        body['wget_status'] = 'ok'
        body['week_json'] = json.dumps(inner, ensure_ascii=False)
        body['what_to_do_next'] = 'Statement week loaded. Say nothing about this result.'
    else:
        body['wget_status'] = 'error'
        body['week_json'] = '{}'
        body['what_to_do_next'] = 'The statement week service failed.'
""", "wget_status")

HOOK_DECIDE = hook("""    rc = str(inner.get('responseCode'))
    if ok and rc in ('0', '0.0') and inner.get('statementDate') and inner.get('statementDueDate'):
        body['decide_status'] = 'ok'
        body['new_stmt_raw'] = str(inner.get('statementDate'))
        body['new_due_raw'] = str(inner.get('statementDueDate'))
        body['what_to_do_next'] = 'Preview loaded. Nothing has been changed yet.'
    else:
        body['decide_status'] = 'error'
        body['what_to_do_next'] = 'The preview service failed. Nothing was changed.'
""", "decide_status")

HOOK_CHANGE = hook("""    rc = str(inner.get('responseCode'))
    if ok and str(inner.get('exitState') or '').upper() == 'OK' and rc in ('0', '0.0'):
        body['change_status'] = 'ok'
        body['what_to_do_next'] = 'The statement week was changed.'
    else:
        body['change_status'] = 'error'
        body['what_to_do_next'] = 'The change failed. Do not say it was changed.'
""", "change_status")

def code_fn(src):
    assert '{{' not in src and '}}' not in src, src[:80]
    return {"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": src},
                                                              "timeout_ms": {"type": "number", "default": 10000}}}}}

def eq(var, val):
    return {"variable": var, "operator": "equals", "operand": val}

def cond_any(var, vals):
    return {"logic": "or", "conditions": [eq(var, v) for v in vals]}

def cond_all(*cs):
    return {"logic": "or", "conditions": [{"logic": "and", "conditions": list(cs)}]}

def T(target, desc, cond):
    return {"target_node": target, "description": desc, "condition": cond}

ALWAYS = {"operator": "always"}

def passnode(name, ntype, pre, transitions, default, on_enter=None, mapping=None):
    n = {"name": name, "node_type": ntype, "passthrough": True, "passthrough_default_transition": default,
         "on_enter": on_enter or {"type": "silent"}, "disable_inactivity_monitor": True,
         "pre_actions": pre, "transitions": transitions + [T(default, "always", ALWAYS)]}
    if mapping:
        n["response_mapping"] = [{"path": "data." + m, "variable": m} for m in mapping]
    if ntype == "api_request":
        n["suppress_tool_results"] = True
    return n

nodes = {}

# ---------------- shared python helpers (inlined in code nodes) ----------------
HELP = r'''
import json, re, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
def w3(n):
    p = []
    h = n // 100
    t = (n % 100) // 10
    o = n % 10
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    p = []
    for val, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        if n >= val:
            k = n // val
            n = n % val
            if nm == 'bin' and k == 1:
                p.append('bin')
            else:
                p.append(w3(k) + ' ' + nm)
    if n:
        p.append(w3(n))
    return ' '.join(p)
def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0
CUR = {'TL': ('Türk Lirası', 'lira', 'kuruş'), 'USD': ('Dolar', 'dolar', 'sent'), 'EUR': ('Euro', 'euro', 'sent'), 'GBP': ('İngiliz Sterlini', 'sterlin', 'peni')}
def amount(x, cur):
    v = int(round(abs(num(x)) * 100))
    major = v // 100
    minor = v % 100
    full, small, sub = CUR[cur]
    if minor == 0:
        return words(major) + ' ' + full
    if major == 0:
        return words(minor) + ' ' + sub
    return words(major) + ' ' + small + ' ' + words(minor) + ' ' + sub
def suf(text):
    s = text.strip()
    last = s.split(' ')[-1] if s else ''
    lw = last.lower()
    if re.match(r'^[0-9]+$', lw):
        lw = words(int(lw)).split(' ')[-1]
    vow = [c for c in lw if c in 'aeıioöuü']
    v = vow[-1] if vow else 'e'
    hv = {'a': 'ı', 'ı': 'ı', 'e': 'i', 'i': 'i', 'o': 'u', 'u': 'u', 'ö': 'ü', 'ü': 'ü'}[v]
    cons = 't' if (lw and lw[-1] in 'fstkçşhp') else 'd'
    sx = cons + hv + 'r'
    if last[:1].isupper() or re.match(r'^[0-9]+$', last):
        return s + "'" + sx
    return s + sx
def pdate(s):
    try:
        return datetime.datetime.strptime(str(s).strip(), '%d.%m.%Y').date()
    except Exception:
