# ------------- side intents shared by conversation nodes -------------
SIDE = {"name": "side_intent", "type": "string",
        "enum_values": ["none", "agent", "pay", "dispute", "other_person", "non_turkish"],
        "description": "Based only on the customer's latest message: agent = asks for a human/customer representative; pay = wants to pay the debt or asks how/where to pay; dispute = says the debt/amount is wrong or a payment they made is not showing; other_person = asks about or wants a transaction on someone else's card (spouse, parent, child, friend); non_turkish = speaks a language other than Turkish; none = anything else.",
        "min_confidence": 0.6}

def side_transitions():
    return [
        T("say_agent", "Customer asks for a human agent", cond_any("side_intent", ["agent"])),
        T("say_pay", "Customer wants to pay", cond_any("side_intent", ["pay"])),
        T("say_dispute", "Customer disputes the debt or a missing payment", cond_any("side_intent", ["dispute"])),
        T("say_security", "Customer asks about another person's card", cond_any("side_intent", ["other_person"])),
        T("say_non_turkish", "Customer does not speak Turkish", cond_any("side_intent", ["non_turkish"])),
    ]

NO_TOOL = " Do not call any tool in this turn."

def conv(name, on_enter, task, extraction, transitions, max_turns=8, first_only=False):
    n = {"name": name, "node_type": "conversation", "on_enter": on_enter, "task_message": task + NO_TOOL,
         "extraction_schema": extraction + [SIDE], "transitions": side_transitions() + transitions,
         "max_node_turns": max_turns, "max_turn_transition": "say_tries"}
    if first_only:
        n["on_enter_first_entry_only"] = True
    return n

